cssCode:
.sliced-text {
  font-size: 70px; font-weight: 900; color: #fff;
  font-family: sans-serif; position: relative;
  text-transform: uppercase; cursor: pointer;
}
.sliced-text::before, .sliced-text::after {
  content: attr(data-text); position: absolute; top: 0; left: 0;
  width: 100%; height: 100%; transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.sliced-text::before {
  color: #00ffcc; clip-path: polygon(0 0, 100% 0, 100% 50%, 0 50%);
}
.sliced-text::after {
  color: #ff007f; clip-path: polygon(0 50%, 100% 50%, 100% 100%, 0 100%);
}
.sliced-text:hover::before { transform: translate(-10px, -10px); }
.sliced-text:hover::after { transform: translate(10px, 10px); }

